Rules.InvariantScript:
//acesso indevido de Jet blast
If(
    varPerfilUser <> "Base",
    ClearCollect(
        col_jetBlastRegistros,
        Sort(
            '14.8-tbl_JetBlast',
            jetBlast_id,
            SortOrder.Descending
        )
    ),
    ClearCollect(
        col_jetBlastRegistros,
        Sort(
            Filter(
                '14.8-tbl_JetBlast',
                jetBlast_aeroporto = varAeroUser
            ),
            jetBlast_id,
            SortOrder.Descending
        )
    )
)

Set(
    var_redirectAN,
    Blank()
);
Navigate(
    frmHome,
    ScreenTransition.Fade
)

Reset(cmbJetBlastBloco);
Reset(cmbJetBlastAeroporto);
Reset(dtpJetBlastDtfInicio);
Reset(dtpJetBlastDtfTermino);
Reset(cmbStatus_8);
Reset(txtJetBlastBuscar)

SortByColumns(
    Filter(
        '14.8-tbl_JetBlast',

        // ✅ Aeroporto — opcional
        IsBlank(cmbJetBlastAeroporto.Selected.Aeroporto) ||
        jetBlast_aeroporto = cmbJetBlastAeroporto.Selected.Aeroporto,

        // ✅ Status — opcional
        IsBlank(cmbStatus_8.Selected.Value) ||
        Status = cmbStatus_8.Selected.Value,

        // ✅ Data Início — opcional
        IsBlank(dtpJetBlastDtfInicio.SelectedDate) ||
        jetBlast_data >= DateTimeValue(dtpJetBlastDtfInicio.SelectedDate),

        // ✅ Data Término — opcional
        IsBlank(dtpJetBlastDtfTermino.SelectedDate) ||
        jetBlast_data < DateAdd(
            DateTimeValue(dtpJetBlastDtfTermino.SelectedDate),
            1,
            TimeUnit.Days
        ),

        // ✅ Buscar por ID — opcional
        IsBlank(txtJetBlastBuscar.Text) ||
        ID = Value(txtJetBlastBuscar.Text)
    ),
    "ID",
    SortOrder.Descending
)

Navigate(
    ScreenDesdobramentos,
    ScreenTransition.Fade,
    {
        var_desdobramentosSelect: {
            ID: Value(ThisItem.jetBlast_id),
            PROTOCOLO: Text(Label_protocolo_14.Text),
            CRIADOR: Text(ThisItem.'Criado por'.DisplayName),
            DESCRICAO: Text(ThisItem.jetBlast_ocorrenciaDesc)
        }
    }
)

Navigate(
    ScreenAnaliseSafety,
    ScreenTransition.Fade,
    {
        var_item_id: ThisItem.ID,
        var_numPortalUnico: ThisItem.NumeroPortalUnico,
        var_analiseSfaty: ThisItem.AnaliseSafety
    }
)

Navigate(
    ScreenExcluir,
    ScreenTransition.Fade,
    {
        var_modulo: var_tituloModulo,
        var_item: ThisItem,
        var_protocolo: Label_protocolo_14.Text
    }
)
